import{_ as e}from"./chunks/ptz-camera.BFf5oNXY.js";import{_ as r,a as i,b as t,c as o,d as s,e as c,f as n}from"./chunks/rbq10-charger.7uvTks7d.js";import{_ as d}from"./chunks/battery.DVQhiztz.js";import{_ as l}from"./chunks/docking-station.MKYdxThc.js";import{_ as h,o as p,c as m,a5 as u}from"./chunks/framework.CcrBcQWS.js";const S=JSON.parse('{"title":"Accessories","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/product-descriptions/accessories.md","filePath":"manual/product-descriptions/accessories.md","lastUpdated":1787021357000}'),g={name:"manual/product-descriptions/accessories.md"};function b(f,a,y,v,_,q){return p(),m("div",null,[...a[0]||(a[0]=[u('<h1 id="accessories" tabindex="-1">Accessories <a class="header-anchor" href="#accessories" aria-label="Permalink to &quot;Accessories&quot;">​</a></h1><p>RBQ supports a range of optional accessories that extend the robot for field missions and development work — sensing, onboard compute and connectivity, and power infrastructure.</p><h2 id="sensing" tabindex="-1">Sensing <a class="header-anchor" href="#sensing" aria-label="Permalink to &quot;Sensing {#sensing}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+e+'" alt=""><h3 id="ptz-camera">PTZ Camera<a class="header-anchor" href="#ptz-camera" aria-label="Permalink to PTZ Camera"></a></h3><p>A Pan-Tilt-Zoom camera that mounts on the RBQ body. Provides high-resolution video streaming for surveillance and reconnaissance missions with remote pan, tilt, and zoom control via the GUI and API.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/related-products/ptz-camera">Specifications →</a></div><div class="rbq-card"><img src="'+r+'" alt=""><h3 id="lidar-mid-360">LIDAR (mid-360)<a class="header-anchor" href="#lidar-mid-360" aria-label="Permalink to LIDAR (mid-360)"></a></h3><p>The Livox MID-360 is a compact 3D LiDAR with a hemispherical field of view (360° × 59°). Used for SLAM, obstacle detection, and autonomous navigation. Connects via Ethernet.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/related-products/lidar#mid-360">Specifications →</a></div><div class="rbq-card"><img src="'+i+'" alt=""><h3 id="lidar-os1-32">LIDAR (OS1-32)<a class="header-anchor" href="#lidar-os1-32" aria-label="Permalink to LIDAR (OS1-32)"></a></h3><p>The Ouster OS1-32 is a 360° spinning LiDAR with 32 channels that delivers dense point clouds for wide-area 3D mapping.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/related-products/lidar#os1-32">Specifications →</a></div></div><h2 id="compute-connectivity" tabindex="-1">Compute &amp; Connectivity <a class="header-anchor" href="#compute-connectivity" aria-label="Permalink to &quot;Compute &amp;amp; Connectivity {#compute-connectivity}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+t+'" alt=""><h3 id="user-pc-module">User-PC Module<a class="header-anchor" href="#user-pc-module" aria-label="Permalink to User-PC Module"></a></h3><p>An embedded compute board that mounts inside the RBQ payload bay. Runs user applications, AI inference, and custom sensor processing directly on the robot. Offers multiple I/O interfaces for sensor integration.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/interface/network#onboard-pcs-and-ip-addresses">Network &amp; IP →</a></div><div class="rbq-card"><img src="'+o+'" alt=""><h3 id="hub-module">Hub Module<a class="header-anchor" href="#hub-module" aria-label="Permalink to Hub Module"></a></h3><p>An interface hub that expands the number of usable <code>12V-LAN</code> ports, so more accessories can be connected at once. Simplifies wiring for multi-sensor payloads.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/interface/external-port">External ports →</a></div><div class="rbq-card"><img src="'+s+'" alt=""><h3 id="wifi-lte-gps-module">Wifi Module / LTE/GPS Module<a class="header-anchor" href="#wifi-lte-gps-module" aria-label="Permalink to Wifi Module / LTE/GPS Module"></a></h3><p>Wireless communication modules for remote operation. The WiFi module enables high-bandwidth local communication, while the LTE/GPS module provides wide-area cellular connectivity combined with positioning.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/interface/network">Network →</a></div></div><h2 id="power-charging" tabindex="-1">Power &amp; Charging <a class="header-anchor" href="#power-charging" aria-label="Permalink to &quot;Power &amp;amp; Charging {#power-charging}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+d+'" alt=""><h3 id="battery">Battery<a class="header-anchor" href="#battery" aria-label="Permalink to Battery"></a></h3><p>The detachable battery pack used by the RBQ. For long-duration operation, swap in a charged pack instead of waiting for a recharge.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/related-products/battery">Specifications →</a></div><div class="rbq-card"><img src="'+c+'" alt=""><h3 id="battery-charging-tray">Battery Charging Tray<a class="header-anchor" href="#battery-charging-tray" aria-label="Permalink to Battery Charging Tray"></a></h3><p>A two-bay tray for charging battery packs on their own, detached from the robot. To charge the packs without removing them, use the RBQ10 charger instead.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/related-products/battery">Battery specifications →</a></div><div class="rbq-card"><img src="'+n+'" alt=""><h3 id="rbq10-charger">RBQ10 Charger<a class="header-anchor" href="#rbq10-charger" aria-label="Permalink to RBQ10 Charger"></a></h3><p>The supplied charger, which connects directly to the charging port on top of the robot. Supports standard AC input and charges the battery packs in place.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/operation/charging">How to charge →</a></div><div class="rbq-card"><img src="'+l+'" alt=""><h3 id="docking-station">Docking Station<a class="header-anchor" href="#docking-station" aria-label="Permalink to Docking Station"></a></h3><p class="rbq-card-badges"><span class="rbq-badge">Dog House · Coming soon</span></p><p>An autonomous docking station that allows the RBQ to self-dock for automatic battery charging and storage. Eliminates manual battery swap for long-duration deployment scenarios.</p><a class="rbq-card-cta" href="/RBQ/nightly/manual/related-products/docking-station">Specifications →</a></div></div>',8)])])}const A=h(g,[["render",b]]);export{S as __pageData,A as default};
